package com.aitutor.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final long exp; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long exp){if(secret==null||secret.isBlank()) throw new IllegalStateException("JWT_SECRET must be configured before starting NovaTutor"); if(secret.getBytes(StandardCharsets.UTF_8).length<32) throw new IllegalStateException("JWT_SECRET must be at least 32 bytes"); key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.exp=exp;} public String token(String email){return Jwts.builder().subject(email).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+exp)).signWith(key).compact();} public String email(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();} }
